/* js/store.js */
/* Armazenamento local: login, configurações, favoritos e progresso ("continuar"). */
var Store = (function () {
  var P = 'iptvs.';
  var mem = {};

  /* ---- perfis ----
     Favoritos, progresso, vistos e canais recentes são de cada perfil.
     O perfil "Principal" (p1) usa as chaves antigas, então nada do histórico atual se perde. */
  var PROFILE_KEYS = { fav: 1, progress: 1, watched: 1, recentLive: 1, favLog: 1, progDel: 1, clearedAt: 1 };   // por perfil E por lista
  /* avisos de mudança (a sincronização com a conta escuta): fn(tipo, perfil, lista) */
  var listeners = [];
  function onChange(fn) { listeners.push(fn); }
  function fire(kind) { var pid = curId(), lid = curList(); listeners.forEach(function (fn) { try { fn(kind, pid, lid); } catch (e) {} }); }
  var LIST_KEYS = { account: 1 };                                             // só por lista
  function rawGet(k, def) {
    if (mem.hasOwnProperty(k)) return mem[k];
    var v = def;
    try {
      var raw = localStorage.getItem(P + k);
      if (raw != null) v = JSON.parse(raw);
    } catch (e) {}
    mem[k] = v;
    return v;
  }
  function rawSet(k, v) {
    mem[k] = v;
    try { localStorage.setItem(P + k, JSON.stringify(v)); } catch (e) {}
  }
  function rawDel(k) {
    delete mem[k];
    try { localStorage.removeItem(P + k); } catch (e) {}
  }
  function curId() { return rawGet('profile', 'p1') || 'p1'; }
  /* chave com prefixo de perfil e de lista. Perfil "p1" e lista "l1" usam as chaves antigas
     (é onde já está o histórico que existia antes). */
  function pk(k, pid, lid) {
    pid = pid || curId(); lid = lid || curList();
    if (PROFILE_KEYS[k]) return (pid !== 'p1' ? 'pf.' + pid + '.' : '') + (lid !== 'l1' ? 'ls.' + lid + '.' : '') + k;
    if (LIST_KEYS[k]) return (lid !== 'l1' ? 'ls.' + lid + '.' : '') + k;
    return k;
  }

  /* ---- listas (cada cliente pode ter várias) ----
     { id, name, type: 'xtream' | 'm3u', server, username, password, url } */
  function lists() {
    var l = rawGet('lists', null);
    if (!l) {
      // migração: o login antigo vira a lista "l1"
      var c = rawGet('creds', null);
      l = [];
      if (c && c.username && c.password) {
        var host = String(c.server || '').replace(/^https?:\/\//, '');
        l.push({ id: 'l1', name: host || 'Minha lista', type: 'xtream', server: c.server, username: c.username, password: c.password });
      }
      rawSet('lists', l);
      if (l.length) rawSet('activeList', 'l1');
    }
    return l;
  }
  function curList() { return rawGet('activeList', null) || 'l1'; }
  function activeList() {
    var id = curList(), l = lists();
    for (var i = 0; i < l.length; i++) if (l[i].id === id) return l[i];
    return null;
  }
  function saveList(item) {
    var l = lists();
    if (!item.id) {
      // a primeira lista usa "l1" (chaves sem prefixo)
      var used = {}; l.forEach(function (x) { used[x.id] = 1; });
      item.id = used.l1 ? 'l' + Date.now().toString(36) : 'l1';
      l.push(item);
    } else if (l.some(function (x) { return x.id === item.id; })) {
      l = l.map(function (x) { return x.id === item.id ? Object.assign({}, x, item) : x; });
    } else {
      l.push(item);   // id escolhido por quem chama (ex.: listas da conta, "c<id>")
    }
    rawSet('lists', l);
    return item;
  }
  function setActiveList(id) { rawSet('activeList', id); }
  function deleteList(id) {
    profiles().forEach(function (p) { Object.keys(PROFILE_KEYS).forEach(function (k) { rawDel(pk(k, p.id, id)); }); });
    Object.keys(LIST_KEYS).forEach(function (k) { rawDel(pk(k, null, id)); });
    var l = lists().filter(function (x) { return x.id !== id; });
    rawSet('lists', l);
    if (curList() === id) { if (l[0]) setActiveList(l[0].id); else rawDel('activeList'); }
  }
  function get(k, def) { return rawGet(pk(k), def); }
  /* leitura/gravação de outro perfil/lista (usado pela sincronização) */
  function getFor(k, pid, lid, def) { return rawGet(pk(k, pid, lid), def); }
  function setFor(k, pid, lid, v) { rawSet(pk(k, pid, lid), v); }
  function set(k, v) { rawSet(pk(k), v); }
  function del(k) { rawDel(pk(k)); }

  var COLORS = ['#7c5cff', '#ff6b6b', '#2fd47c', '#ffb547', '#3fa7ff', '#ff5fc8'];
  function profiles() {
    var l = rawGet('profiles', null);
    if (!l || !l.length) l = [{ id: 'p1', name: 'Principal', color: COLORS[0], kids: false }];
    return l;
  }
  /* perfis alterados aqui e ainda não enviados para a conta: profDirty {id:1}; excluídos: profDel {id:t} */
  function saveProfiles(l, fromSync) {
    rawSet('profiles', l);
    if (!fromSync) fire('profiles');
  }
  function markProfile(id, deleted) {
    var dd = rawGet('profDirty', {}) || {}, dl = rawGet('profDel', {}) || {};
    if (deleted) { delete dd[id]; dl[id] = Date.now(); } else dd[id] = 1;
    rawSet('profDirty', dd); rawSet('profDel', dl);
  }
  function currentProfile() {
    var id = curId(), l = profiles();
    for (var i = 0; i < l.length; i++) if (l[i].id === id) return l[i];
    return l[0];
  }
  function setProfile(id) { rawSet('profile', id); }
  function addProfile(name, kids) {
    var l = profiles();
    var p = { id: 'p' + Date.now().toString(36), name: name, color: COLORS[l.length % COLORS.length], kids: !!kids, t: Date.now() };
    l.push(p); markProfile(p.id); saveProfiles(l);
    return p;
  }
  function updateProfile(id, changes) {
    var l = profiles();
    l.forEach(function (p) { if (p.id === id) Object.assign(p, changes, { t: Date.now() }); });
    markProfile(id); saveProfiles(l);
  }
  function deleteProfile(id) {
    if (id === 'p1') return;
    dropProfileLocal(id);
    markProfile(id, true);
    fire('profiles');
  }
  /* apaga só deste aparelho (também usado quando o perfil foi excluído em outro aparelho) */
  function dropProfileLocal(id) {
    lists().forEach(function (ls) { Object.keys(PROFILE_KEYS).forEach(function (k) { rawDel(pk(k, id, ls.id)); }); });
    rawSet('profiles', profiles().filter(function (p) { return p.id !== id; }));
    if (curId() === id) setProfile('p1');
  }

  /* ---- configurações ---- */
  var DEFAULTS = { liveFormat: 'ts', hideAdult: false, screenMode: 'fit', autoNext: true, startLastChannel: false, pin: '', sleepMin: 0, startFullscreen: false,
    sort: { live: 'default', movie: 'default', series: 'default' } };

  /* ---- canais vistos recentemente: [{ item, catId, catName, t }] ---- */
  function recentLive() { return get('recentLive', []); }
  function addRecentLive(item, catId, catName) {
    if (!item || item.stream_id == null) return;
    var list = recentLive().filter(function (r) { return String(r.item.stream_id) !== String(item.stream_id); });
    list.unshift({ item: slim(item), catId: catId != null ? String(catId) : null, catName: catName || '', t: Date.now() });
    set('recentLive', list.slice(0, 30));
  }
  function settings() {
    var s = Object.assign({}, DEFAULTS, get('settings', {}));
    s.sort = Object.assign({}, DEFAULTS.sort, s.sort || {});
    return s;
  }
  function setSetting(k, v) { var s = settings(); s[k] = v; set('settings', s); }

  /* ---- favoritos: { live: [item], movie: [item], series: [item] } ---- */
  function favs(type) { var f = get('fav', {}); return f[type] || []; }
  function favKey(type, item) { return String(type === 'series' ? item.series_id : item.stream_id); }
  function isFav(type, item) {
    var k = favKey(type, item);
    return favs(type).some(function (x) { return favKey(type, x) === k; });
  }
  function toggleFav(type, item) {
    var f = get('fav', {});
    var list = f[type] || [];
    var k = favKey(type, item);
    var idx = -1;
    list.forEach(function (x, i) { if (favKey(type, x) === k) idx = i; });
    if (idx >= 0) list.splice(idx, 1); else list.unshift(slim(item));
    f[type] = list;
    set('fav', f);
    var log = get('favLog', {});
    log[type + ':' + k] = { on: idx < 0, t: Date.now() };
    set('favLog', log);
    fire('data');
    return idx < 0;
  }
  function slim(item) {
    var o = {};
    ['stream_id', 'series_id', 'name', 'stream_icon', 'cover', 'rating', 'category_id', 'container_extension', 'num', 'epg_channel_id', 'added', 'last_modified']
      .forEach(function (k) { if (item[k] != null) o[k] = item[k]; });
    return o;
  }

  /* ---- progresso ----
     "movie:ID" | "ep:ID" -> {pos, dur, t, meta}       (assistindo)
     "S:seriesId"         -> {ep, epId, finished, next, t, meta}  (onde parei na série)
     watched              -> { "ep:ID": t, "movie:ID": t }  (já vistos) */
  function progressAll() { return get('progress', {}); }
  function getProgress(key) { return progressAll()[key] || null; }
  function isWatched(key) { return !!get('watched', {})[key]; }
  function markWatched(key) {
    var w = get('watched', {});
    w[key] = Date.now();
    var ks = Object.keys(w);
    if (ks.length > 3000) { ks.sort(function (a, b) { return w[a] - w[b]; }); ks.slice(0, ks.length - 3000).forEach(function (k) { delete w[k]; }); }
    set('watched', w);
  }
  /* dur > 0 e pos/dur > 92% (ou créditos finais) conta como assistido */
  /* saiu do "continuar": guarda quando, para os outros aparelhos também tirarem */
  function dropKey(all, key, del) { if (all[key]) { delete all[key]; del[key] = Date.now(); } }
  function saveProgress(key, pos, dur, meta) {
    var all = progressAll(), del = get('progDel', {}), before = JSON.stringify(all[key] || null);
    var finished = dur > 0 && (pos / dur > 0.92 || (dur > 600 && dur - pos < 90));
    if (finished) {
      dropKey(all, key, del);    // terminou: sai do "continuar"
      markWatched(key);
    } else if (pos > 15) {
      all[key] = { pos: Math.floor(pos), dur: Math.floor(dur || 0), t: Date.now(), meta: meta || {} };
      delete del[key];
    } else if (!all[key]) {
      if (!meta || !meta.seriesId) { set('progress', all); return; }
    }
    if (meta && meta.seriesId) {
      if (finished && !meta.next) {
        dropKey(all, 'S:' + meta.seriesId, del);   // terminou a série
      } else {
        delete del['S:' + meta.seriesId];
        all['S:' + meta.seriesId] = {
          ep: key, epId: meta.epId, label: meta.label, finished: finished,
          next: meta.next || null, t: Date.now(), meta: meta.series || {}
        };
      }
    }
    // limita tamanho
    var keys = Object.keys(all);
    if (keys.length > 300) {
      keys.sort(function (a, b) { return all[a].t - all[b].t; });
      keys.slice(0, keys.length - 300).forEach(function (k) { delete all[k]; });
    }
    // tira registros de remoção com mais de 60 dias
    var old = Date.now() - 60 * 86400000;
    Object.keys(del).forEach(function (k) { if (del[k] < old) delete del[k]; });
    set('progress', all);
    set('progDel', del);
    if (finished || JSON.stringify(all[key] || null) !== before) fire('data');
  }
  function clearProgress() { del('progress'); del('watched'); del('progDel'); set('clearedAt', Date.now()); fire('data'); }

  return {
    lists: lists, activeList: activeList, saveList: saveList, setActiveList: setActiveList, deleteList: deleteList,
    profiles: profiles, saveProfiles: saveProfiles, currentProfile: currentProfile, setProfile: setProfile,
    addProfile: addProfile, updateProfile: updateProfile, deleteProfile: deleteProfile,
    get: get, set: set, del: del,
    settings: settings, setSetting: setSetting,
    favs: favs, isFav: isFav, toggleFav: toggleFav, slim: slim,
    progressAll: progressAll, getProgress: getProgress, saveProgress: saveProgress, clearProgress: clearProgress,
    isWatched: isWatched, markWatched: markWatched,
    recentLive: recentLive, addRecentLive: addRecentLive,
    onChange: onChange, getFor: getFor, setFor: setFor, curList: curList, dropProfileLocal: dropProfileLocal,
    raw: rawGet, rawSet: rawSet, favKey: favKey
  };
})();

