/* js/cache.js */
/* Cache persistente no aparelho (IndexedDB) para as listas do servidor.
   Ao abrir o app as categorias e listas aparecem na hora (do cache) e são
   atualizadas em segundo plano. Se o IndexedDB não estiver disponível, funciona
   só em memória. */
var DiskCache = (function () {
  var DB = 'iptvs-cache', STORE = 'kv';
  var dbp = null;

  function open() {
    if (dbp) return dbp;
    dbp = new Promise(function (resolve) {
      // se o banco não responder (travado/corrompido), segue sem cache
      var timer = setTimeout(function () { resolve(null); }, 2000);
      var done = function (v) { clearTimeout(timer); resolve(v); };
      try {
        if (!window.indexedDB) return done(null);
        var r = indexedDB.open(DB, 1);
        r.onupgradeneeded = function () { r.result.createObjectStore(STORE); };
        r.onsuccess = function () {
          var db = r.result;
          db.onversionchange = function () { db.close(); dbp = null; };
          done(db);
        };
        r.onerror = function () { done(null); };
        r.onblocked = function () { done(null); };
      } catch (e) { done(null); }
    });
    return dbp;
  }

  function tx(mode, fn) {
    return open().then(function (db) {
      if (!db) return null;
      return new Promise(function (resolve) {
        var timer = setTimeout(function () { resolve(null); }, 4000);
        var res = resolve;
        resolve = function (v) { clearTimeout(timer); res(v); };
        try {
          var t = db.transaction(STORE, mode);
          var st = t.objectStore(STORE);
          var req = fn(st);
          t.oncomplete = function () { resolve(req ? req.result : null); };
          t.onerror = t.onabort = function () { resolve(null); };
        } catch (e) { resolve(null); }
      });
    });
  }

  return {
    get: function (key) { return tx('readonly', function (st) { return st.get(key); }); },
    set: function (key, data) { return tx('readwrite', function (st) { st.put({ t: Date.now(), data: data }, key); }); },
    clear: function () { return tx('readwrite', function (st) { st.clear(); }); }
  };
})();

