/* js/api.js */
/* Cliente da API Xtream Codes (player_api.php), usada pelo painel XUI.one.
   O link M3U (get.php?username=..&password=..) usa o mesmo login, mas a API
   é muito mais leve: carrega só a categoria aberta, com capa, sinopse e nota. */
var Api = (function () {
  var creds = null;
  var cache = {};

  function enc(s) { return encodeURIComponent(s); }

  function normServer(s) {
    s = (s || '').trim();
    if (!s) return '';
    if (!/^https?:\/\//i.test(s)) s = 'http://' + s;
    var m = s.match(/^(https?:\/\/[^\/?#]+)/i);
    return m ? m[1] : s;
  }

  /* Aceita o link M3U completo e extrai servidor, usuário e senha */
  function parseLink(s) {
    s = (s || '').trim();
    if (s.indexOf('username=') < 0) return null;
    try {
      var u = new URL(/^https?:\/\//i.test(s) ? s : 'http://' + s);
      var user = u.searchParams.get('username');
      var pass = u.searchParams.get('password');
      if (!user || !pass || user.charAt(0) === '{') return { server: u.protocol + '//' + u.host };
      return { server: u.protocol + '//' + u.host, username: user, password: pass };
    } catch (e) { return null; }
  }

  /* ---- erros amigáveis ----
     kind: offline | network | timeout | server | auth | limit | notfound | busy | invalid */
  function netError(kind, status) {
    var M = {
      offline: ['Sem internet', 'A TV está sem conexão com a internet. Verifique o Wi-Fi ou o cabo de rede.'],
