      if (tt && tt.length) for (var j = 0; j < tt.length; j++) out.text.push({ id: j, label: tt[j].label || langName(tt[j].language, 'Legenda ' + (j + 1)), sel: tt[j].mode === 'showing' });
      return out;
    },
    setAudio: function (id) {
      var h = this.lib && this.lib.kind === 'hls' ? this.lib.p : null;
      if (h) { h.audioTrack = id; return; }
      var at = video.audioTracks;
      if (at) for (var i = 0; i < at.length; i++) at[i].enabled = i === id;
    },
    setText: function (id) {
      var h = this.lib && this.lib.kind === 'hls' ? this.lib.p : null;
      if (h) { h.subtitleTrack = id; return; }
      var tt = video.textTracks;
      if (tt) for (var i = 0; i < tt.length; i++) tt[i].mode = i === id ? 'showing' : 'disabled';
    },
    applyScreen: function () { video.style.objectFit = Store.settings().screenMode === 'fill' ? 'fill' : 'contain'; },
    destroy: function () {
      this.cb = null;
      if (this.lib) {
        try {
          if (this.lib.kind === 'mpegts') { this.lib.p.pause(); this.lib.p.unload(); this.lib.p.detachMediaElement(); this.lib.p.destroy(); }
          if (this.lib.kind === 'hls') this.lib.p.destroy();
        } catch (e) {}
      }
      this.lib = null;
      try { video.pause(); } catch (e) {}
      video.removeAttribute('src');
      try { video.load(); } catch (e) {}
    }
  };

  /* ================= OSD / CONTROLES ================= */
  function osdVisible() { return osd.classList.contains('show'); }
  /* passive: OSD aberto só para informar (início do vídeo, troca de canal) —
     nenhum botão focado, então o primeiro OK não pausa sem querer */
  var passive = false;
  function showOsd(focusWhat) {
    osd.classList.add('show');
    layer.classList.add('osd-on');
    if (focusWhat) {
      passive = false;
      setFocusC(focusWhat === 'bar' ? $('osd-bar') : ctrlByKey(focusWhat) || ctrls[0]);
    } else if (!focusC && !passive) setFocusC(ctrlByKey('pp') || ctrls[0]);
    armHide();
  }
  function showOsdPassive() {
    passive = true;
    setFocusC(null);
    showOsd();
  }
  function armHide() {
    clearTimeout(osdTimer);
    osdTimer = setTimeout(function () {
      if (state === 'playing' && !panel && seekTarget == null) hideOsd();
      else armHide();
    }, 5000);
  }
  function hideOsd() { osd.classList.remove('show'); layer.classList.remove('osd-on'); clearTimeout(osdTimer); }

  function ctrlByKey(k) { for (var i = 0; i < ctrls.length; i++) if (ctrls[i]._k === k) return ctrls[i]; return null; }
  function setFocusC(el) {
    if (focusC) focusC.classList.remove('on');
    focusC = el;
    if (el) el.classList.add('on');
  }

  function buildCtrls() {
    ctrlBox.innerHTML = '';
    ctrls = [];
    focusC = null;
    var live = opts.kind === 'live';
    function add(k, icon, label, fn) {
      var b = document.createElement('button');
      b.className = 'pbtn pf';
      b._k = k;
      b.innerHTML = '<i>' + icon + '</i><span>' + esc(label) + '</span>';
      b.addEventListener('click', function () { setFocusC(b); fn(); armHide(); });
      ctrlBox.appendChild(b);
      ctrls.push(b);
      return b;
    }
    if (live) {
      add('chp', ICON.up, 'Canal anterior', function () { zap(-1); });
      add('chn', ICON.down, 'Próximo canal', function () { zap(1); });
      add('chb', ICON.back.replace('>10<', '><'), 'Último canal', lastChannel);
      if (opts.list && opts.list.length > 1) add('chl', ICON.list, 'Canais', openChannels);
      if (opts.onGuide) add('gd', ICON.tracks.replace('M7 13.5h4M13 13.5h4M7 10h10', 'M2.5 10h19M9 5v14'), 'Guia', function () { opts.onGuide(opts); });
    } else {
      add('rs', ICON.restart, 'Do início', function () { seekTo(0); });
      add('bk', ICON.back, '-10s', function () { seekBy(-1, 10); });
      add('pp', ICON.pause, 'Pausar', togglePause);
      add('fw', ICON.fwd, '+10s', function () { seekBy(1, 10); });
      if (opts.next) add('nx', ICON.next, 'Próximo ep.', playNext);
      if (opts.episodes) add('ep', ICON.list, 'Episódios', openEpisodes);
    }
    add('tr', ICON.tracks, 'Áudio e legenda', openTracks);
    add('sc', ICON.screen, Store.settings().screenMode === 'fill' ? 'Tela: esticar' : 'Tela: ajustar', toggleScreen);
    if (Platform.canFullscreen) add('fs', ICON.screen.replace('M3 9V4h5M21 9V4h-5M3 15v5h5M21 15v5h-5', 'M3 8V3h5M3 3l6 6M21 8V3h-5M21 3l-6 6M3 16v5h5M3 21l6-6M21 16v5h-5M21 21l-6-6'),
      Platform.isFullscreen() ? 'Sair da tela cheia' : 'Tela cheia', toggleFs);
    if (hooks.cycleSleep) add('sl', ICON.clock, hooks.sleepLabel(), function () {
      var b = ctrlByKey('sl'); var t = hooks.cycleSleep(); if (b) b.querySelector('span').textContent = t;
    });
  }
  function updatePlayBtn() {
    var b = ctrlByKey('pp');
    if (!b) return;
    var paused = state === 'paused';
    b.querySelector('i').innerHTML = paused ? ICON.play : ICON.pause;
    b.querySelector('span').textContent = paused ? 'Continuar' : 'Pausar';
  }

  /* navegação dentro do OSD */
  function osdMove(dir) {
    var bar = $('osd-bar');
    var hasBar = opts.kind !== 'live';
    var idx = ctrls.indexOf(focusC);
    if (focusC === bar) {
      if (dir === 'left') seekBy(-1);
      else if (dir === 'right') seekBy(1);
      else if (dir === 'down') setFocusC(ctrlByKey('pp') || ctrls[0]);
      return;
    }
    if (dir === 'up' && hasBar) { setFocusC(bar); return; }
    if (dir === 'left' && idx > 0) setFocusC(ctrls[idx - 1]);
    if (dir === 'right' && idx < ctrls.length - 1) setFocusC(ctrls[idx + 1]);
  }

  function flashIcon(t) {
    var el = $('p-icon'); el.innerHTML = t; el.className = 'p-icon show';
    clearTimeout(el._t); el._t = setTimeout(function () { el.className = 'p-icon'; }, 700);
  }
  function flashMsg(t) {
    var el = $('p-icon'); el.textContent = t; el.className = 'p-icon show wide';
    clearTimeout(el._t); el._t = setTimeout(function () { el.className = 'p-icon'; }, 1500);
  }

  /* ================= ERROS ================= */
  var errRetries = 0, lastPos = 0, errKind = null, errFocus = 0, retryTimer = null, stableTimer = null;

  /* classifica erros do AVPlay (TV) */
  function avErr(e) {
    var n = String((e && (e.name || e.message)) || e || '');
    if (/CONNECTION|NETWORK|TIMEOUT|TIMED_OUT/i.test(n)) return { kind: 'network', detail: n };
    if (/NOT_SUPPORTED|UNSUPPORTED|CODEC|FORMAT/i.test(n)) return { kind: 'format', detail: n };
    if (/NO_SUCH_FILE|INVALID_URI/i.test(n)) return { kind: 'http', detail: n };
    return { kind: 'unknown', detail: n };
  }

  function errText(kind) {
    var live = opts && opts.kind === 'live';
    var T = {
      offline: ['Sem internet', 'A conexão com a internet caiu. Assim que ela voltar, o vídeo continua sozinho.'],
      network: ['Servidor fora do ar', 'Não foi possível conectar ao servidor da lista. Ele pode estar fora do ar ou a internet está oscilando.'],
      timeout: ['Servidor lento', 'O servidor da lista demorou demais para responder.'],
      server: ['Servidor instável', 'O servidor da lista está com problemas agora. Tente de novo em alguns minutos.'],
      auth: ['Acesso recusado', 'O servidor recusou o vídeo. Pode ser limite de telas (outro aparelho assistindo) ou assinatura vencida.'],
      limit: ['Limite de telas', 'Já tem outro aparelho assistindo com esta conta. Feche lá e tente de novo.'],
      notfound: live ? ['Canal fora do ar', 'Este canal não está transmitindo no momento. Tente outro canal (▲ ▼).']
        : ['Conteúdo indisponível', 'Este arquivo não está mais disponível no servidor.'],
      busy: ['Muitas tentativas', 'O servidor pediu para aguardar um pouco antes de tentar de novo.'],
      format: ['Formato não suportado', Platform.isTizen ? 'A TV não conseguiu tocar este arquivo.'
        : 'O navegador não toca este tipo de arquivo (áudio/vídeo). Na TV ele costuma funcionar.'],
      unstable: ['O vídeo parou', 'A transmissão foi interrompida. Tente de novo.']
    };
    return T[kind] || T.unstable;
  }

  function setSpinMsg(t) { $('p-spin-msg').textContent = t || ''; }

  function showErr(kind, status) {
    clearTimeout(retryTimer);
    errKind = kind;
    state = 'error';
    var t = errText(kind);
    $('p-error-title').textContent = t[0];
    $('p-error-msg').textContent = t[1];
    $('p-error-code').textContent = status ? 'código ' + status : '';
    errFocus = 0;
    updateErrBtns();
    $('p-err-next').style.display = opts && opts.kind === 'live' && opts.list && opts.list.length > 1 ? '' : 'none';
    errBox.classList.add('show');
    spinner.classList.remove('show');
    setSpinMsg('');
    hideOsd();
  }
  function errBtns() {
    return [$('p-err-retry'), $('p-err-next'), $('p-err-back')].filter(function (b) { return b.style.display !== 'none'; });
  }
  function updateErrBtns() {
    errBtns().forEach(function (b, i) { b.classList.toggle('on', i === errFocus); });
  }
  function retryNow() {
    if (!opts) return;
    errRetries = 0;
    start(opts.kind === 'live' ? 0 : lastPos, true);
  }

  function handleError(err) {
    if (!opts) return;
    err = err || { kind: 'unknown' };
    if (typeof err === 'string') err = { kind: 'unknown', detail: err };
    // no PC, se o .ts falhar tenta HLS automaticamente uma vez
    if (opts.kind === 'live' && !Platform.isTizen && !triedFallback && !Api.isM3u() && /\.ts$/.test(opts.url) && err.kind !== 'http') {
      triedFallback = true;
      opts.url = opts.url.replace(/\.ts$/, '.m3u8');
      start(0, true);
      return;
    }
    var pos = opts.kind === 'live' ? 0 : backend.time();
    if (pos > 0) lastPos = pos;
    if (!Platform.isOnline()) { showErr('offline'); return; }
    // oscilação: reconecta sozinho até 3 vezes, voltando para o mesmo ponto
    var transient = err.kind === 'network' || err.kind === 'unknown' || (err.kind === 'http' && err.status >= 500);
    var maxRetries = opts.kind === 'live' ? 3 : 5;
    if (transient && errRetries < maxRetries) {
      errRetries++;
      state = 'buffering';
      spinner.classList.add('show');
      setSpinMsg('Conexão instável, reconectando... (' + errRetries + '/' + maxRetries + ')');
      clearTimeout(retryTimer);
      retryTimer = setTimeout(function () { if (opts) start(opts.kind === 'live' ? 0 : lastPos, true); }, 1500 * errRetries);
      return;
    }
    if (err.kind === 'format') { showErr('format'); return; }
    // pergunta ao servidor o motivo real (404, 403, 502...)
    state = 'buffering';
    spinner.classList.add('show');
    setSpinMsg('Verificando o motivo...');
    var url = opts.url;
    Api.probe(url).then(function (r) {
      if (!opts || opts.url !== url) return;
      var kind = r.kind === 'ok' ? (err.kind === 'http' ? 'format' : 'unstable') : r.kind;
      if (kind === 'invalid') kind = 'unstable';
      showErr(kind, r.status);
    });
  }

  // internet caiu / voltou durante o vídeo
  Platform.onNetworkChange(function (on) {
    if (!opts) return;
    if (!on) {
      if (backend && opts.kind !== 'live') { var p = backend.time(); if (p > 0) lastPos = p; }
      showErr('offline');
    } else if (state === 'error' && /^(offline|network|timeout|unstable)$/.test(errKind || '')) {
      setTimeout(retryNow, 1500);
    }
  });

  function setState(s, msg) {
    if (s === 'error') { handleError(msg); return; }
    state = s;
    spinner.classList.toggle('show', s === 'buffering' || s === 'loading');
    errBox.classList.remove('show');
    if (s === 'playing') {
      setSpinMsg('');
      // depois de 20s tocando sem erro, zera o contador de reconexões
      clearTimeout(stableTimer);
      stableTimer = setTimeout(function () { errRetries = 0; }, 20000);
      if (backend && opts && opts.kind !== 'live') { var t = backend.time(); if (t > 0) lastPos = t; }
    }
    updatePlayBtn();
    if (s === 'ended') onEnded();
    if (s === 'paused') { showOsd(); clearTimeout(osdTimer); }
    if (s === 'playing' && osdVisible()) armHide();
  }

  function tick() {
    var sl = hooks.sleepLeft ? hooks.sleepLeft() : 0;
    $('osd-clock').innerHTML = (sl ? '<span class="osd-sleep">Timer ' + sl + ' min</span>' : '') + hhmm(Date.now());
    var sb = ctrlByKey('sl'); if (sb && hooks.sleepLabel) sb.querySelector('span').textContent = hooks.sleepLabel();
    if (!opts || opts.kind === 'live' || !backend) return;
    var cur = seekTarget != null ? seekTarget : backend.time();
    var dur = backend.duration();
    $('osd-cur').textContent = fmt(cur);
    $('osd-dur').textContent = dur ? '-' + fmt(Math.max(0, dur - cur)) : '--:--';
    var pct = dur ? Math.min(100, cur / dur * 100) : 0;
    $('osd-fill').style.width = pct + '%';
    var sk = $('osd-seek'), tip = $('osd-tip');
    sk.style.left = pct + '%';
    tip.style.left = pct + '%';
    tip.textContent = fmt(cur);
    var seeking = seekTarget != null;
    sk.classList.toggle('show', seeking || focusC === $('osd-bar'));
    tip.classList.toggle('show', seeking);
    checkNext(backend.time(), dur);
  }

  function saveProgress() {
    if (!opts || opts.kind === 'live' || !backend || !opts.progressKey) return;
    var t = backend.time(), d = backend.duration();
    if (t > 0) Store.saveProgress(opts.progressKey, t, d, opts.meta);
    if (d > 0 && !opts._durSaved) {
      opts._durSaved = true;
      try { localStorage.setItem('iptvs.lastVod', JSON.stringify({ url: opts.url, title: opts.title, dur: d })); } catch (e) {}
    }
  }

  function loadEpg() {
    var box = $('osd-epg');
    box.innerHTML = '';
    if (!opts || opts.kind !== 'live' || !opts.item) return;
    var id = opts.item.stream_id;
    Api.shortEpg(id).then(function (list) {
      if (!opts || !opts.item || opts.item.stream_id !== id) return;
      var now = Date.now();
      list = list.filter(function (e) { return e.end > now; });
      if (!list.length) { box.innerHTML = '<div class="nx">Sem guia de programação</div>'; return; }
      var html = '';
      list.slice(0, 2).forEach(function (e, i) {
        var pct = i === 0 && e.end > e.start ? Math.max(0, Math.min(100, (now - e.start) / (e.end - e.start) * 100)) : 0;
        html += '<div class="' + (i ? 'nx' : 'now') + '"><span class="t">' + hhmm(e.start) + ' - ' + hhmm(e.end) + '</span>' + esc(e.title) +
          (i === 0 ? '<div class="epg-bar"><i style="width:' + pct + '%"></i></div>' : '') + '</div>';
      });
      box.innerHTML = html;
    }).catch(function () { box.innerHTML = ''; });
  }

  function fillOsd() {
    $('osd-title').textContent = opts.title || '';
    $('osd-sub').textContent = opts.subtitle || '';
    $('osd-barwrap').style.display = opts.kind === 'live' ? 'none' : '';
    buildCtrls();
    loadEpg();
  }

  var loadId = 0;
  function start(startSec, isRetry) {
    if (!isRetry) errRetries = 0;
    clearTimeout(retryTimer);
    errKind = null;
    errBox.classList.remove('show');
    setState('loading');
    if (isRetry && errRetries) setSpinMsg('Conexão instável, reconectando... (' + errRetries + '/3)');
    resetNext();
    var id = ++loadId;
    backend.load(opts.url, opts.kind === 'live', startSec || 0, function (s, msg) {
      if (id !== loadId || !layer.classList.contains('active')) return;   // evento de um carregamento antigo
      if (state === 'error' && s !== 'error') return;
      setState(s, msg);
    });
  }

  function open(o) {
    if (opts) stopCurrent();
    closePanel();
    opts = o;
    triedFallback = false;
    liveRetries = 0;
    lastPos = o.startPos || 0;
    if (o.kind === 'live') {
      if (liveCur && String(liveCur.id) !== String(o.item && o.item.stream_id)) o.prevCh = liveCur;
      liveCur = liveCtx(o);
    }
    backend = Platform.isTizen ? TizenBackend : WebBackend;
    // guarda o último filme/episódio: o "Testar conexão" (Config) mede a velocidade com ele
    if (o.kind !== 'live') { try { localStorage.setItem('iptvs.lastVod', JSON.stringify({ url: o.url, title: o.title })); } catch (e) {} }
    layer.classList.add('active');
    document.body.classList.add('playing');
    fillOsd();
    start(o.startPos || 0);
    showOsdPassive();
    if (o.startPos > 30) flashMsg('Continuando de ' + fmt(o.startPos));
    clearInterval(progressTimer); progressTimer = setInterval(saveProgress, 10000);
    clearInterval(uiTimer); uiTimer = setInterval(tick, 500);
    tick();
  }

  function stopCurrent() {
    saveProgress();
    resetNext();
    if (backend) backend.destroy();
  }

  function close() {
    if (!opts) return;
    stopCurrent();
    closePanel();
    var o = opts;
    opts = null;
    clearInterval(progressTimer); clearInterval(uiTimer);
    clearTimeout(seekTimer); seekTarget = null;
    clearTimeout(retryTimer); clearTimeout(stableTimer);
    setSpinMsg('');
    layer.classList.remove('active');
    document.body.classList.remove('playing');
    hideOsd();
    errBox.classList.remove('show');
    spinner.classList.remove('show');
    state = 'idle';
    if (o.onClose) o.onClose();
  }

  function onEnded() {
    if (opts && opts.kind === 'live') {
      // stream ao vivo caiu: reconecta sozinho algumas vezes
      if (liveRetries++ < 5) { setTimeout(function () { if (opts && opts.kind === 'live') start(0, true); }, 1500); return; }
      setState('error', 'O canal parou de transmitir.');
      return;
    }
    if (opts && opts.progressKey) Store.saveProgress(opts.progressKey, 1, 1, opts.meta); // marca como visto
    if (opts && opts.next && Store.settings().autoNext !== false) { playNext(); return; }
    close();
  }

  /* ---- próximo episódio ---- */
  function resetNext() {
    clearInterval(next.timer);
    next.shown = false; next.dismissed = false;
    $('p-next').classList.remove('show');
  }
  function checkNext(cur, dur) {
    if (!opts || !opts.next || !dur || dur < 120) return;
    var left = dur - cur;
    if (left > 45) { if (next.shown) hideNextCard(); next.dismissed = false; return; }
    if (left <= 25 && !next.shown && !next.dismissed && state === 'playing') showNextCard();
  }
  function showNextCard() {
    var n = opts.next;
    next.shown = true;
    next.left = 10;
    next.focus = 0;
    $('pn-title').textContent = n.label + (n.title ? ' · ' + n.title : '');
    var th = $('pn-thumb');
    th.style.backgroundImage = n.thumb ? 'url("' + String(n.thumb).replace(/"/g, '%22') + '")' : '';
    updateNextCard();
    $('p-next').classList.add('show');
    clearInterval(next.timer);
    next.timer = setInterval(function () {
      if (state !== 'playing') return;
      next.left--;
      updateNextCard();
      if (next.left <= 0 && Store.settings().autoNext !== false) playNext();
    }, 1000);
  }
  function updateNextCard() {
    $('pn-count').textContent = Store.settings().autoNext !== false ? 'em ' + Math.max(0, next.left) + 's' : '';
    $('pn-go').classList.toggle('on', next.focus === 0);
    $('pn-cancel').classList.toggle('on', next.focus === 1);
  }
  function hideNextCard() {
    clearInterval(next.timer);
    next.shown = false;
    $('p-next').classList.remove('show');
  }
  function dismissNext() { hideNextCard(); next.dismissed = true; }
  function playNext() {
    if (!opts || !opts.next) return;
    var fn = opts.next.play;
    saveProgress();
    if (opts.progressKey && backend && backend.duration() && backend.duration() - backend.time() < 120) {
      Store.saveProgress(opts.progressKey, 1, 1, opts.meta);
    }
    hideNextCard();
    fn();
  }
  $('pn-go').addEventListener('click', playNext);
  $('pn-cancel').addEventListener('click', dismissNext);

  /* ---- painel lateral genérico (lista com janela) ---- */
  function openPanel(p) {
    panel = p;
    if (panel.sel == null || !isSel(panel.sel)) panel.sel = firstSel(0, 1);
    $('p-panel').classList.add('show');
    renderPanel();
    clearTimeout(osdTimer);
  }
  function closePanel() {
    panel = null;
    $('p-panel').classList.remove('show');
    if (osdVisible()) armHide();
  }
  function isSel(i) { var it = panel.items[i]; return it && !it.header; }
  function firstSel(i, d) { while (panel.items[i] && panel.items[i].header) i += d; return panel.items[i] ? i : panel.sel; }
  function renderPanel() {
    var head = $('pp-head');
    head.innerHTML = panel.title;
    $('pp-hint').textContent = panel.hint || 'OK: escolher · Voltar: fechar';
    var box = $('pp-list');
    box.innerHTML = '';
    var N = 9, total = panel.items.length;
    var from = Math.max(0, Math.min(panel.sel - 4, total - N));
    var to = Math.min(total, from + N);
    if (!total) { box.innerHTML = '<div class="pp-empty">' + esc(panel.empty || 'Nada aqui') + '</div>'; return; }
    for (var i = from; i < to; i++) {
      (function (i) {
        var it = panel.items[i];
        var el = document.createElement(it.header ? 'div' : 'button');
        el.className = it.header ? 'pp-h' : 'pp-i' + (i === panel.sel ? ' on' : '') + (it.cur ? ' cur' : '') + (it.cls ? ' ' + it.cls : '');
        el.innerHTML = it.header ? esc(it.label)
          : '<span class="l">' + esc(it.label) + '</span>' + (it.sub ? '<span class="s">' + esc(it.sub) + '</span>' : '') +
            (it.pct ? '<span class="pg"><i style="width:' + it.pct + '%"></i></span>' : '');
        if (!it.header) el.addEventListener('click', function () { panel.sel = i; pickPanel(); });
        box.appendChild(el);
      })(i);
    }
    if (from > 0) box.insertAdjacentHTML('afterbegin', '<div class="pp-more">▲</div>');
    if (to < total) box.insertAdjacentHTML('beforeend', '<div class="pp-more">▼</div>');
  }
  function panelMove(d) {
    var i = panel.sel + d;
    while (panel.items[i] && panel.items[i].header) i += d;
    if (panel.items[i]) { panel.sel = i; renderPanel(); }
  }
  function pickPanel() {
    var p = panel, it = p.items[p.sel];
    if (it && p.pick) p.pick(it, p.sel);
  }
