  /* lazy-load de imagens */
  var io = ('IntersectionObserver' in window) ? new IntersectionObserver(function (entries) {
    entries.forEach(function (en) {
      if (en.isIntersecting) { var el = en.target; loadImg(el); io.unobserve(el); }
    });
  }, { rootMargin: '400px' }) : null;
  function loadImg(el) {
    var src = el.getAttribute('data-src');
    if (!src) return;
    el.removeAttribute('data-src');
    if (el.tagName === 'IMG') {
      el.onerror = function () { el.style.visibility = 'hidden'; };
      el.src = src;
    } else el.style.backgroundImage = 'url("' + src.replace(/"/g, '%22') + '")';
  }
  /* Capas do TMDB vêm enormes (600x900 ou original). Pedimos o tamanho certo:
     economiza memória de vídeo da TV e deixa a rolagem fluida. */
  var IMG = { poster: 'w342', thumb: 'w300', big: 'w780', detail: 'w500' };
  function imgSize(src, size) {
    if (!src || !size || !IMG[size]) return src;
    return String(src).replace(/(image\.tmdb\.org\/t\/p\/)[^\/]+\//, '$1' + IMG[size] + '/');
  }
  function bgUrl(src, size) { return src ? 'url("' + String(imgSize(src, size)).replace(/"/g, '%22') + '")' : ''; }
  function lazy(el, src, size) {
    if (!src) return;
    src = imgSize(src, size);
    el.setAttribute('data-src', src);
    if (io) io.observe(el); else loadImg(el);
  }

  /* ---------------- telas / histórico ---------------- */
