    stack.push(name);
    activate(name, data, true);
  }
  function replace(name, data) {
    var prev = stack.pop();
    if (prev) $('s-' + prev).classList.remove('active');
    stack.push(name);
    activate(name, data, true);
  }
  function activate(name, data, fresh) {
    var el = $('s-' + name);
    el.classList.add('active');
    Nav.setRoot(el);
    if (screens[name] && screens[name].enter) screens[name].enter(data, fresh);
    if (!fresh && el._focus && Nav.visible(el._focus) && el.contains(el._focus)) Nav.focus(el._focus);
    else if (!Nav.current() || !el.contains(Nav.current()) || !Nav.visible(Nav.current())) Nav.focus(screens[name].firstFocus ? screens[name].firstFocus() : Nav.first());
  }
  var lastBack = 0;
  function back() {
    if (stack.length > 1) {
      var leaving = stack.pop();
      $('s-' + leaving).classList.remove('active');
      if (screens[leaving].leave) screens[leaving].leave();
      activate(stack[stack.length - 1], null, false);
