  /* monta a lista a partir do formulário (o link M3U de painel Xtream vira login Xtream) */
  function formList() {
    var name = $('in-name').value.trim();
    if (LG.tab === 'm3u') {
      var url = $('in-url').value.trim();
      if (!url) return { err: 'Cole o link da lista' };
      if (!/^https?:\/\//i.test(url)) url = 'http://' + url;
      var x = Api.parseLink(url);
      if (x && x.username && x.password) return { type: 'xtream', server: x.server, username: x.username, password: x.password, name: name, fromLink: true };
      return { type: 'm3u', url: url, name: name };
    }
    var srv = $('in-server').value, user = $('in-user').value.trim(), pass = $('in-pass').value.trim();
    var link = Api.parseLink(srv);
    if (link) { srv = link.server; if (link.username) { user = link.username; pass = link.password; } }
    srv = Api.normServer(srv);
    if (!srv || !user || !pass) return { err: 'Preencha servidor, usuário e senha' };
    return { type: 'xtream', server: srv, username: user, password: pass, name: name };
  }
  function defaultName(l) {
    var host = '';
