  /* uma linha horizontal com título; reaproveita o container para manter o foco */
  /* sig: "assinatura" do conteúdo — se não mudou, a linha não é refeita (evita travadas) */
  function homeRow(id, title, count, sig, build) {
    var box = $('home-rows');
    var wrap = $('hr-' + id);
    if (wrap && wrap._sig === sig) return;
    var els = sig ? build() : [];
    if (!els || !els.length) { if (wrap) wrap.parentNode.removeChild(wrap); return; }
    if (!wrap) {
      wrap = h('div', 'hrow'); wrap.id = 'hr-' + id;
      wrap.appendChild(h('h3'));
      var row = h('div', 'row scroll-x'); row.setAttribute('data-zone', 'hr-' + id); row.setAttribute('data-entry-first', '');
      wrap.appendChild(row);
      // mantém a ordem definida em HOME_ROWS
      var order = HOME_ROWS.indexOf(id), next = null;
      Array.prototype.forEach.call(box.children, function (c) { if (!next && HOME_ROWS.indexOf(c.id.slice(3)) > order) next = c; });
      box.insertBefore(wrap, next);
    }
    wrap._sig = sig;
    wrap.querySelector('h3').innerHTML = esc(title) + (count ? '<small>' + count + '</small>' : '');
    var r = wrap.querySelector('.row');
    var cur = Nav.current(), keepIdx = cur && r.contains(cur) ? Array.prototype.indexOf.call(r.children, cur) : -1;
    var keepScroll = r.scrollLeft;
    r.innerHTML = '';
    els.forEach(function (e) { r.appendChild(e); });
    r.scrollLeft = keepScroll;
    if (keepIdx >= 0) Nav.focus(r.children[Math.min(keepIdx, r.children.length - 1)], { noScroll: true });
    r._last = null;
  }
  var HOME_ROWS = ['continue', 'recentLive', 'favs', 'newMovies', 'newSeries'];
