    var hero = $('hero'), first = cont[0];
    if (first) {
      var m = first.p.meta, pr = first.type === 'movie' ? first.p : first.ep;
      $('hero-kicker').textContent = first.type === 'series' && first.p.finished ? 'Próximo episódio' : 'Continuar assistindo';
