      $('hero-sub').textContent = continueLabel(first);
      $('hero-prog').style.width = (pr && pr.dur ? Math.round(pr.pos / pr.dur * 100) : 0) + '%';
      $('hero-play').textContent = first.type === 'series' && first.p.finished ? '▶ Assistir ' + first.p.next.label : '▶ Continuar';
