    homeRow('favs', 'Favoritos', '', favSig.replace(/\|/g, '') ? favSig : '', function () {
    var favEls = [];
    Store.favs('live').forEach(function (it) {
      favEls.push(logoMini(it, 'Canal', function () { var l = Store.favs('live'); playLive(l, l.indexOf(it) >= 0 ? l.indexOf(it) : 0, '★ Favoritos', null); }));
    });
    ['movie', 'series'].forEach(function (t) {
      Store.favs(t).forEach(function (it) {
        favEls.push(posterMini(it, t === 'movie' ? 'Filme' : 'Série', function () { show('detail', { type: t, item: it, list: Store.favs(t) }); }));
      });
    });
    return favEls;
    });
    // adicionados recentemente (usa a mesma lista da busca geral, guardada no aparelho)
    loadNewRows();
  }

  var newRowsTimer = null;
  function loadNewRows() {
    clearTimeout(newRowsTimer);
    newRowsTimer = setTimeout(function () {
      [['movie', 'newMovies', 'Filmes adicionados recentemente'], ['series', 'newSeries', 'Séries adicionadas recentemente']].forEach(function (cfg) {
        Promise.all([Api.streams(cfg[0], null), Api.categories(cfg[0]).catch(function () { return []; })]).then(function (r) {
          if (stack[stack.length - 1] !== 'home') return;
          var adult = {};
          if (adultBlocked()) r[1].forEach(function (c) { if (isAdult(c.category_name)) adult[c.category_id] = 1; });
          var seen = {};
          var list = r[0].filter(function (it) {
            if (adult[it.category_id] || !(+(it.added || it.last_modified))) return false;
            var k = norm(it.name); if (seen[k]) return false; seen[k] = 1; return true;
          });
          list.sort(function (a, b) { return (+(b.added || b.last_modified)) - (+(a.added || a.last_modified)); });
          list = list.slice(0, 24);
          homeRow(cfg[1], cfg[2], '', list.map(function (it) { return it.stream_id || it.series_id; }).join(','), function () {
            return list.map(function (it, i) {
              return posterMini(it, '', function () { show('detail', { type: cfg[0], item: it, list: list, index: i }); });
