  /* ================= BUSCA GERAL ================= */
  var GS = { index: null, loading: null, errors: [] };
  screens.search = {
    enter: function (data, fresh) {
      if (!fresh) return;
      ensureIndex();
      runSearch();
      setTimeout(function () { var i = $('gs-input'); Nav.focus(i); try { i.focus(); } catch (e) {} }, 60);
    },
    firstFocus: function () { return $('gs-input'); }
  };
  function gsStatus(t) { $('gs-status').textContent = t || ''; }
  function ensureIndex() {
    if (GS.index || GS.loading) return GS.loading;
    var types = ['live', 'movie', 'series'], left = 3;
    GS.errors = [];
    gsStatus('Preparando a busca... na primeira vez pode levar alguns segundos.');
    GS.loading = Promise.all(types.map(function (t) {
      return Promise.all([Api.streams(t, null), Api.categories(t).catch(function () { return []; })]).then(function (r) {
        left--;
        if (left) gsStatus('Preparando a busca... (faltam ' + left + ')');
        var adult = {};
        r[1].forEach(function (c) { if (isAdult(c.category_name)) adult[c.category_id] = 1; });
        return r[0].map(function (it) { return { it: it, n: norm(it.name), adult: !!adult[it.category_id] }; });
      }, function (e) { left--; GS.errors.push(SECTION_NAME[t]); return []; });
    })).then(function (res) {
      GS.index = { live: res[0], movie: res[1], series: res[2] };
      GS.lastIndex = GS.index;
      GS.loading = null;
      gsStatus(GS.errors.length ? 'Não foi possível carregar: ' + GS.errors.join(', ') + '. O restante está disponível.' : '');
      if (GS.errors.length) GS.index = null; // tenta de novo na próxima vez
      if (stack[stack.length - 1] === 'search') runSearch();
    });
    return GS.loading;
  }
  function runSearch() {
    var box = $('gs-results');
    var q = norm($('gs-input').value).trim();
    var idx = GS.index || GS.lastIndex;
    box.innerHTML = '';
    if (q.length < 2) { if (!GS.loading) gsStatus('Digite pelo menos 2 letras.'); return; }
    if (!idx) return;
    var words = q.split(/\s+/);
    var hide = adultBlocked();
    var total = 0;
    [['live', 'Canais'], ['movie', 'Filmes'], ['series', 'Séries']].forEach(function (cfg) {
      var t = cfg[0], seen = {};
      var hits = idx[t].filter(function (e) {
        if (hide && e.adult) return false;
        for (var i = 0; i < words.length; i++) if (e.n.indexOf(words[i]) < 0) return false;
        return true;
      });
      // começa com o termo primeiro, depois nomes mais curtos
      hits.sort(function (a, b) {
        var sa = a.n.indexOf(q) === 0 ? 0 : 1, sb = b.n.indexOf(q) === 0 ? 0 : 1;
        return sa - sb || a.n.length - b.n.length;
      });
      if (t !== 'live') hits = hits.filter(function (e) { if (seen[e.n]) return false; seen[e.n] = 1; return true; });
      total += hits.length;
      if (!hits.length) return;
      var list = hits.slice(0, 60).map(function (e) { return e.it; });
      var wrap = h('div', 'hrow');
      wrap.appendChild(h('h3', null, esc(cfg[1]) + '<small>' + hits.length + (hits.length > 60 ? ' · mostrando 60' : '') + '</small>'));
      var row = h('div', 'row scroll-x'); row.setAttribute('data-zone', 'gs-' + t); row.setAttribute('data-entry-first', '');
      list.forEach(function (it, i) {
        row.appendChild(t === 'live'
          ? logoMini(it, it.num ? 'Canal ' + it.num : '', function () { playLive(list, i, 'Busca: ' + $('gs-input').value, null); })
          : posterMini(it, '', function () { show('detail', { type: t, item: it, list: list, index: i }); }));
      });
      wrap.appendChild(row);
      box.appendChild(wrap);
    });
    if (!GS.loading) gsStatus(total ? '' : 'Nada encontrado para "' + $('gs-input').value + '".');
  }
  $('gs-input').addEventListener('input', debounce(runSearch, 350));
  $('gs-input').onenter = function () { var f = $('gs-results').querySelector('.f'); if (f) Nav.focus(f); };

  /* itens do "continuar assistindo" */
  function continueEntries(type) {
    var all = Store.progressAll();
    var out = [];
    Object.keys(all).forEach(function (k) {
      var p = all[k];
      if (!p || !p.meta) return;
      if (k.indexOf('movie:') === 0 && (!type || type === 'movie')) out.push({ type: 'movie', key: k, p: p });
      if (k.indexOf('S:') === 0 && (!type || type === 'series') && p.meta.item) {
        var ep = all[p.ep] || null;
        if (p.finished ? p.next : true) out.push({ type: 'series', key: k, p: p, ep: ep });
      }
    });
    out.sort(function (a, b) { return b.p.t - a.p.t; });
    return out;
  }
  function continueItem(en) { return en.p.meta.item; }
  /* retoma direto no player, sem passar pela tela de detalhe */
  function resumeEntry(en) {
    var it = continueItem(en);
    if (!it) return;
    if (en.type === 'movie') playMovie(it, { resume: true, backdrop: en.p.meta.backdrop });
    else resumeSeries(it);
  }
  function continueLabel(en) {
    if (en.type === 'movie') return 'Parou em ' + Player.fmt(en.p.pos) + ' de ' + Player.fmt(en.p.dur);
    if (en.p.finished && en.p.next) return 'Próximo: ' + en.p.next.label;
    return (en.p.label || '') + (en.ep ? ' · parou em ' + Player.fmt(en.ep.pos) : '');
  }
  /* ================= BROWSE ================= */
  var B = { section: null, cats: [], cat: null, items: [], filtered: [], rendered: 0, counts: {}, reqId: 0 };

  screens.browse = {
    enter: function (data, fresh) {
      if (!fresh) { refreshFavMarks(); return; }
      if (data && data.section !== B.section) {
        B.section = data.section;
        B.cat = null; B.items = []; B.filtered = []; B.cats = [];
        $('cat-search').value = ''; $('item-search').value = '';
        $('grid').innerHTML = ''; $('cat-list').innerHTML = '';
        $('b-cat').textContent = ''; $('b-count').textContent = '';
        $('s-browse').querySelectorAll('[data-zone]').forEach(function (z) { z._last = null; });
        loadCategories();
      } else if (B.cat && /^(fav|continue|recent)$/.test(B.cat.id)) {
        selectCategory(B.cat, false);
      }
      $('b-section').textContent = SECTION_NAME[B.section];
      $('guide-btn').style.display = B.section === 'live' ? '' : 'none';
      $('grid').className = 'grid scroll-y' + (B.section === 'live' ? ' live' : '');
    },
    firstFocus: function () { return document.querySelector('#cat-list .cat.sel') || document.querySelector('#cat-list .cat') || $('cat-search'); }
  };

  function loadCategories() {
    var section = B.section;
    loading(true);
    Api.categories(section).then(function (cats) {
      loading(false);
      if (section !== B.section) return;
      var hide = adultHiddenFully();
      B.adultIds = {};
      cats.forEach(function (c) { if (isAdult(c.category_name)) B.adultIds[c.category_id] = 1; });
      var list = [{ id: 'fav', name: '★ Favoritos' }];
      if (section !== 'live') list.push({ id: 'continue', name: '▶ Continuar assistindo' });
      else list.push({ id: 'recent', name: '• Vistos recentemente' });
      list.push({ id: 'all', name: section === 'live' ? 'Todos os canais' : 'Todos (pode demorar)' });
      cats.forEach(function (c) {
        if (hide && B.adultIds[c.category_id]) return;
        list.push({ id: String(c.category_id), name: cleanName(c.category_name) || c.category_name, locked: !!B.adultIds[c.category_id] });
      });
      B.cats = list;
      B.counts[section] = B.counts[section] || {};
      renderCats();
      // abre a primeira categoria real (ou favoritos se houver)
      var real = list.filter(function (c) { return !/^(fav|continue|recent|all)$/.test(c.id); });
      var safe = real.filter(function (c) { return !B.adultIds[c.id]; });
      var startCat = Store.favs(section).length ? list[0] : (safe[0] || real[0] || list[0]);
      if (section === 'movie' || section === 'series') {
        if (continueEntries(section).length) startCat = list[1];
      }
      selectCategory(startCat, false);
      var sel = document.querySelector('#cat-list .cat.sel');
      if (sel) Nav.focus(sel);
    }).catch(function (e) {
      loading(false);
      if (section !== B.section) return;
      $('cat-list').innerHTML = '';
      var btn = showError($('grid'), e, function () { $('grid').innerHTML = ''; loadCategories(); }, 'empty');
      if (btn) Nav.focus(btn);
    });
  }

  function catCount(c) {
    if (c.id === 'fav') return Store.favs(B.section).length;
    if (c.id === 'continue') return continueEntries(B.section).length;
    if (c.id === 'recent') return Store.recentLive().length;
    var n = (B.counts[B.section] || {})[c.id];
    return n == null ? '' : n;
  }

  function renderCats() {
    var q = norm($('cat-search').value);
    var box = $('cat-list');
    box.innerHTML = '';
    var frag = document.createDocumentFragment();
    B.cats.forEach(function (c) {
      if (q && norm(c.name).indexOf(q) < 0) return;
      var el = h('button', 'cat f' + (B.cat && B.cat.id === c.id ? ' sel' : '') + (c.locked && adultBlocked() ? ' locked' : ''));
      el.innerHTML = '<span class="n">' + esc(c.name) + '</span><span class="c">' + catCount(c) + '</span>';
      el._cat = c;
      el.addEventListener('click', function () {
        if (c.locked && adultBlocked()) {
          unlockAdult().then(function (ok) {
            if (!ok) return;
            Array.prototype.forEach.call($('cat-list').children, function (x) { x.classList.remove('locked'); });
            selectCategory(c, true);
          });
          return;
        }
        // mesma categoria já carregada: só entra na grade
        if (B.cat && B.cat.id === c.id && B.loaded === c.id) {
          var f = $('grid').querySelector('.card');
          if (f) { Nav.focus(f); return; }
        }
        selectCategory(c, true);
      });
      frag.appendChild(el);
    });
    box.appendChild(frag);
    if (!box.children.length) box.appendChild(h('div', 'empty', 'Nenhuma categoria'));
  }
  function updateCatCounts() {
    Array.prototype.forEach.call($('cat-list').children, function (el) {
      if (el._cat) el.querySelector('.c').textContent = catCount(el._cat);
    });
  }

  // a categoria só troca com OK / clique (andar pela lista não carrega nada)
  Nav.onFocus(function (el) {
    if (el.parentNode === $('grid')) maybeRenderMore(el);
  });

  /* caixa de erro com "Tentar de novo" dentro de um container */
  function showError(box, err, retry, cls) {
    box.innerHTML = '';
    var d = h('div', 'errbox' + (cls ? ' ' + cls : ''));
    d.appendChild(h('div', 'err-t', esc(err && err.title || 'Algo deu errado')));
    d.appendChild(h('div', 'err-m', esc(err && err.message || String(err || ''))));
    if (retry) {
      var b = h('button', 'btn primary f', 'Tentar de novo');
      b.addEventListener('click', retry);
      d.appendChild(b);
    }
    box.appendChild(d);
    return d.querySelector('.btn');
  }

  function selectCategory(c, focusGrid) {
    var section = B.section;
    B.cat = c;
    Array.prototype.forEach.call($('cat-list').children, function (el) { el.classList.toggle('sel', el._cat === c); });
    $('b-cat').textContent = c.name;
    $('b-count').textContent = '';
    $('item-search').placeholder = 'Buscar em ' + c.name;
    $('grid')._last = null;
    var req = ++B.reqId;
    B.loaded = null;
    var p;
    if (c.id === 'fav') p = Promise.resolve(Store.favs(section).slice());
    else if (c.id === 'recent') p = Promise.resolve(Store.recentLive().map(function (r) { return r.item; }));
    else if (c.id === 'continue') {
      B.contEntries = continueEntries(section).filter(function (en) { return !!continueItem(en); });
      p = Promise.resolve(B.contEntries.map(continueItem));
    }
    else if (c.id === 'all') p = Api.streams(section, null);
    else p = Api.streams(section, c.id);
    var slow = setTimeout(function () { loading(true); }, 250);
    $('grid').innerHTML = '';
    p.then(function (items) {
      clearTimeout(slow); loading(false);
      if (req !== B.reqId || section !== B.section) return;
      if (adultBlocked() && /^(all|fav|recent|continue)$/.test(c.id)) {
        items = items.filter(function (it) { return !B.adultIds[it.category_id]; });
      }
      B.items = items;
      B.loaded = c.id;
      if (c.id === 'all') {
        // aproveita para contar itens de todas as categorias
        var cnt = {};
        items.forEach(function (it) { cnt[it.category_id] = (cnt[it.category_id] || 0) + 1; });
        Object.keys(cnt).forEach(function (k) { B.counts[section][k] = cnt[k]; });
      }
      if (!/^(fav|continue|recent)$/.test(c.id)) B.counts[section][c.id] = items.length;
      updateCatCounts();
      applyFilter();
      if (focusGrid) {
        var f = $('grid').querySelector('.card');
        if (f) Nav.focus(f);
      }
    }).catch(function (e) {
      clearTimeout(slow); loading(false);
      if (req !== B.reqId) return;
      var btn = showError($('grid'), e, function () { selectCategory(c, true); }, 'empty');
      if (focusGrid && btn) Nav.focus(btn);
    });
  }

  /* ---- ordenação da grade ---- */
  var SORTS = {
    live: [['default', 'Padrão'], ['az', 'A-Z'], ['num', 'Número']],
    movie: [['default', 'Padrão'], ['recent', 'Mais recentes'], ['az', 'A-Z'], ['rating', 'Nota IMDb']],
    series: [['default', 'Padrão'], ['recent', 'Mais recentes'], ['az', 'A-Z'], ['rating', 'Nota IMDb']]
  };
  function sortMode() { return Store.settings().sort[B.section] || 'default'; }
  function sortLabel() {
    var m = sortMode(), l = SORTS[B.section] || [];
    for (var i = 0; i < l.length; i++) if (l[i][0] === m) return l[i][1];
    return 'Padrão';
  }
  function sortItems(list) {
    var m = sortMode();
    // listas pessoais ficam na ordem em que você viu
    if (m === 'default' || (B.cat && /^(continue|recent)$/.test(B.cat.id))) return list;
    var out = list.slice();
    var coll = (window.Intl && Intl.Collator) ? new Intl.Collator('pt-BR', { sensitivity: 'base', numeric: true }) : null;
    var key = function (x) { return String(x.name || '').replace(/^[^0-9A-Za-zÀ-ÿ]+/, ''); };
    var byName = function (a, b) { return coll ? coll.compare(key(a), key(b)) : key(a).localeCompare(key(b)); };
    if (m === 'az') out.sort(byName);
    else if (m === 'num') out.sort(function (a, b) { return (+a.num || 1e9) - (+b.num || 1e9); });
    else if (m === 'recent') out.sort(function (a, b) { return (+(b.added || b.last_modified) || 0) - (+(a.added || a.last_modified) || 0); });
    else if (m === 'rating') out.sort(function (a, b) { return (parseFloat(b.rating) || 0) - (parseFloat(a.rating) || 0) || byName(a, b); });
    return out;
  }
  $('sort-btn').addEventListener('click', function () {
    var l = SORTS[B.section] || [], m = sortMode(), k = 0;
    for (var i = 0; i < l.length; i++) if (l[i][0] === m) k = i;
    var next = l[(k + 1) % l.length][0];
    var all = Store.settings().sort;
    all[B.section] = next;
    Store.setSetting('sort', all);
    $('sort-btn').textContent = 'Ordem: ' + sortLabel();
    applyFilter();
  });

  function applyFilter() {
    var q = norm($('item-search').value);
    $('sort-btn').textContent = 'Ordem: ' + sortLabel();
    B.filtered = sortItems(q ? B.items.filter(function (it) { return norm(it.name).indexOf(q) >= 0; }) : B.items);
    $('b-count').textContent = B.filtered.length + (B.filtered.length === 1 ? ' item' : ' itens');
    var g = $('grid');
    g.innerHTML = '';
    g.scrollTop = 0;
    g._last = null;
    B.rendered = 0;
    if (!B.filtered.length) {
      var msg = B.cat && B.cat.id === 'fav' ? 'Nenhum favorito ainda. Use o botão ★ nos detalhes (ou a tecla vermelha / F nos canais).'
        : B.cat && B.cat.id === 'continue' ? 'Nada para continuar.'
        : B.cat && B.cat.id === 'recent' ? 'Os canais que você assistir aparecem aqui.' : 'Nada encontrado';
      g.appendChild(h('div', 'empty', esc(msg)));
      return;
    }
    renderMore();
  }

  function renderMore() {
    var g = $('grid');
    var more = g.querySelector('.more'); if (more) more.parentNode.removeChild(more);
    var end = Math.min(B.filtered.length, B.rendered + CHUNK);
    var frag = document.createDocumentFragment();
    for (var i = B.rendered; i < end; i++) frag.appendChild(makeCard(B.filtered[i], i));
    B.rendered = end;
    if (B.rendered < B.filtered.length) { var m = h('div', 'more'); frag.appendChild(m); }
    g.appendChild(frag);
  }
  function maybeRenderMore(el) {
    if (el._idx != null && el._idx > B.rendered - 20 && B.rendered < B.filtered.length) renderMore();
  }
  $('grid').addEventListener('scroll', function () {
    var g = this;
    if (g.scrollTop + g.clientHeight > g.scrollHeight - 600 && B.rendered < B.filtered.length) renderMore();
  });

  function makeCard(it, i) {
    var live = B.section === 'live';
    var el = h('button', 'card f' + (live ? ' live' : ''));
    el._idx = i;
    var img = h('div', 'img');
    var im = document.createElement('img'); im.alt = '';
    img.appendChild(im);
    if (live) lazy(im, it.stream_icon); else lazy(im, it.stream_icon || it.cover, 'poster');
    el.appendChild(img);
    if (live && it.num) el.appendChild(h('span', 'num', esc(it.num)));
    var r = !live && rating(it.rating);
    if (r) el.appendChild(h('span', 'rate', '★ ' + r));
    if (Store.isFav(B.section, it)) el.appendChild(h('span', 'fav', '★'));
    el.appendChild(h('div', 'name', esc(it.name)));
    el.addEventListener('click', function () { openItem(i); });
    return el;
  }
  function refreshFavMarks() {
    Array.prototype.forEach.call($('grid').querySelectorAll('.card'), function (el) {
      var it = B.filtered[el._idx]; if (!it) return;
      var has = el.querySelector('.fav'), fav = Store.isFav(B.section, it);
      if (fav && !has) el.insertBefore(h('span', 'fav', '★'), el.lastChild);
      if (!fav && has) has.parentNode.removeChild(has);
    });
    updateCatCounts();
  }

  function openItem(i) {
    var it = B.filtered[i];
    if (!it) return;
    if (B.section === 'live') {
      var cat = B.cat || {};
      var real = !/^(fav|recent|all)$/.test(cat.id || '');
      playLive(B.filtered, i, cat.name || '', real ? cat.id : null);
      return;
    }
    if (B.cat && B.cat.id === 'continue' && B.contEntries) {
      // "Continuar assistindo": dá play direto de onde parou
      var en = B.contEntries.filter(function (x) { return continueItem(x) === it; })[0];
      if (en) { resumeEntry(en); return; }
    }
    show('detail', { type: B.section, item: it, list: B.filtered, index: i });
  }

  function playLive(list, i, catName, catId) {
    var it = list[i];
    // categoria "recentes"/"favoritos": guarda a categoria original de cada canal
    function remember(item, o) {
      var cid = o && o.catId != null ? o.catId : item.category_id;
      var cname = o && o.catId != null ? o.categoryName : catNameOf(item.category_id);
      Store.addRecentLive(item, cid, cname);
    }
    remember(it, { catId: catId != null ? catId : null, categoryName: catName });
    Player.open({
      kind: 'live', item: it, list: list, index: i, categoryName: catName, catId: catId,
      onGuide: function (o) {
        Player.close();
        openGuide(o.list, o.index, o.categoryName, o.catId);
      },
      title: it.name,
      subtitle: (it.num ? 'Canal ' + it.num : '') + (catName ? '  ·  ' + catName : ''),
      url: Api.streamUrl('live', it.stream_id, Store.settings().liveFormat),
      onClose: function () { if (stack[stack.length - 1] === 'browse') updateCatCounts(); else if (stack[stack.length - 1] === 'home') screens.home.enter(); },
      onZap: function (item, idx, o) {
        remember(item, o);
        // mantém a grade sincronizada com o canal atual
        if (o && o.list === B.filtered) {
          while (idx >= B.rendered && B.rendered < B.filtered.length) renderMore();
          var card = $('grid').children[idx];
          if (card) Nav.focus(card);
        }
      }
    });
  }

  function catNameOf(id) {
    var c = (B.section === 'live' ? B.cats : []).filter(function (x) { return x.id === String(id); })[0];
    return c ? c.name : '';
  }
  /* abre direto no último canal assistido (usado na tela inicial e ao abrir o app) */
  function playLastChannel(entry) {
    entry = entry || Store.recentLive()[0];
    if (!entry) return false;
    var done = function (list) {
      var idx = -1;
      list.forEach(function (c, k) { if (idx < 0 && String(c.stream_id) === String(entry.item.stream_id)) idx = k; });
      if (idx < 0) { list = [entry.item]; idx = 0; }
      playLive(list, idx, entry.catName || '', entry.catId);
    };
    if (entry.catId != null) Api.streams('live', entry.catId).then(done, function () { done([entry.item]); });
    else done(Store.recentLive().map(function (r) { return r.item; }));
    return true;
  }

  $('cat-search').addEventListener('input', debounce(renderCats, 200));
  $('item-search').addEventListener('input', debounce(applyFilter, 300));
  $('cat-search').onenter = function () { var f = document.querySelector('#cat-list .cat'); if (f) Nav.focus(f); };
  $('item-search').onenter = function () { var f = $('grid').querySelector('.card'); if (f) Nav.focus(f); };

  /* ================= GUIA DE PROGRAMAÇÃO (EPG em grade) =================
     Navegação própria (não usa o Nav): só desenha as linhas visíveis e baixa o
     guia de cada canal sob demanda (4 por vez), guardando no aparelho por 3h. */
  var G = { list: [], row: 0, top: 0, cursor: 0, view: 0, data: {}, loading: {}, queue: [], active: 0, catName: '', catId: null };
  var G_MIN = 60000, G_SPAN = 150 * G_MIN, G_STEP = 30 * G_MIN, G_ROWS = 8;
  function gAlign(t) { return Math.floor(t / G_STEP) * G_STEP; }
  function hm(ts) { var d = new Date(ts); return pad(d.getHours()) + ':' + pad(d.getMinutes()); }
  var WEEK = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];
  function dayLabel(ts) {
    var d = new Date(ts), t = new Date(), y = new Date(Date.now() - 864e5), m = new Date(Date.now() + 864e5);
    var same = function (a, b) { return a.toDateString() === b.toDateString(); };
    return same(d, t) ? 'Hoje' : same(d, m) ? 'Amanhã' : same(d, y) ? 'Ontem' : WEEK[d.getDay()] + ' ' + pad(d.getDate()) + '/' + pad(d.getMonth() + 1);
  }

  screens.guide = {
    enter: function (data, fresh) {
      if (fresh && data) {
        G.list = data.list || [];
        G.catName = data.catName || '';
        G.catId = data.catId;
        G.row = Math.max(0, Math.min(G.list.length - 1, data.index || 0));
        G.cursor = Date.now();
        G.view = gAlign(Date.now()) - G_STEP;
        G.top = Math.max(0, Math.min(G.row - 2, G.list.length - G_ROWS));
      }
      $('gd-cat').textContent = G.catName + ' · ' + G.list.length + ' canais';
      gRender();
      clearInterval(G.timer);
      G.timer = setInterval(function () { if (stack[stack.length - 1] === 'guide') gRender(); }, 30000);
    },
    leave: function () { clearInterval(G.timer); G.queue = []; },
    firstFocus: function () { return null; }
  };

  function gLoad(ch) {
    var id = ch.stream_id;
    if (G.data.hasOwnProperty(id) || G.loading[id]) return;
    if (!ch.epg_channel_id) { G.data[id] = []; return; }   // canal sem guia no servidor
    G.loading[id] = 1;
    G.queue.push(ch);
    gPump();
  }
  function gPump() {
    while (G.active < 4 && G.queue.length) {
      var ch = G.queue.shift();
      var idx = G.list.indexOf(ch);
      // pulou da tela enquanto esperava: deixa para depois
      if (idx < G.top - 3 || idx > G.top + G_ROWS + 3) { delete G.loading[ch.stream_id]; continue; }
      G.active++;
      (function (ch) {
        Api.epgTable(ch.stream_id).then(function (l) { G.data[ch.stream_id] = l; }, function () { G.data[ch.stream_id] = null; })
          .then(function () {
            G.active--;
            delete G.loading[ch.stream_id];
            if (stack[stack.length - 1] === 'guide') gRenderSoon();
            gPump();
          });
      })(ch);
    }
  }
  var gSoon = null;
  function gRenderSoon() { clearTimeout(gSoon); gSoon = setTimeout(gRender, 60); }

  /* programa selecionado na linha r (o que contém o cursor, senão o próximo) */
  function gSel(r) {
    var ch = G.list[r]; if (!ch) return null;
    var l = G.data[ch.stream_id];
    if (!l || !l.length) return null;
    for (var i = 0; i < l.length; i++) if (l[i].s <= G.cursor && l[i].e > G.cursor) return l[i];
    for (i = 0; i < l.length; i++) if (l[i].s > G.cursor) return l[i];
    return l[l.length - 1];
  }

  function gRender() {
    var now = Date.now();
    $('gd-clock').textContent = hm(now);
    $('gd-day').textContent = dayLabel(G.cursor);
    // régua de horários
    var ticks = $('gd-ticks'); ticks.innerHTML = '';
    for (var t = G.view; t < G.view + G_SPAN; t += G_STEP) {
      var sp = h('span', null, hm(t)); sp.style.left = ((t - G.view) / G_SPAN * 100) + '%'; ticks.appendChild(sp);
    }
    // linha do "agora"
    var nf = (now - G.view) / G_SPAN, nowEl = $('gd-now');
    nowEl.style.display = nf >= 0 && nf <= 1 ? '' : 'none';
    nowEl.style.left = 'calc(20rem + (100% - 20rem) * ' + nf.toFixed(4) + ')';
    // linhas visíveis
    var box = $('gd-rows'); box.innerHTML = '';
    var end = Math.min(G.list.length, G.top + G_ROWS);
    for (var r = G.top; r < end; r++) box.appendChild(gRow(r, now));
    // pré-carrega um pouco acima/abaixo
    for (r = Math.max(0, G.top - 2); r < Math.min(G.list.length, end + 3); r++) gLoad(G.list[r]);
    gInfo(now);
  }
  function gRow(r, now) {
    var ch = G.list[r], sel = r === G.row, cur = sel ? gSel(r) : null;
    var row = h('div', 'gd-row' + (sel ? ' sel' : ''));
    var c = h('div', 'gd-chan');
    c.appendChild(h('span', 'gd-num', esc(ch.num || '')));
    var im = document.createElement('img'); im.className = 'gd-logo'; im.alt = '';
    im.onerror = function () { im.style.visibility = 'hidden'; };
    if (ch.stream_icon) im.src = ch.stream_icon;
    c.appendChild(im);
    c.appendChild(h('span', 'gd-name', esc(ch.name)));
    c.addEventListener('click', function () { if (G.row === r) gPlay(); else { G.row = r; gRender(); } });
    var line = h('div', 'gd-line');
    var l = G.data[ch.stream_id];
    if (l === undefined || G.loading[ch.stream_id]) line.appendChild(h('div', 'gd-p gd-empty', 'Carregando guia...'));
    else if (!l || !l.length) line.appendChild(h('div', 'gd-p gd-empty' + (sel ? ' on' : ''), l === null ? 'Guia indisponível' : 'Sem programação'));
    else {
      l.forEach(function (p) {
        if (p.e <= G.view || p.s >= G.view + G_SPAN) return;
        var a = Math.max(0, (p.s - G.view) / G_SPAN), b = Math.min(1, (p.e - G.view) / G_SPAN);
        var cls = 'gd-p' + (p.s <= now && p.e > now ? ' now' : p.e <= now ? ' past' : '') + (p === cur ? ' on' : '');
        var el = h('div', cls, (p.s < G.view ? '‹ ' : '') + esc(p.t));
        el.style.left = (a * 100) + '%';
        el.style.width = 'calc(' + ((b - a) * 100) + '% - .15rem)';
        el.addEventListener('click', function () {
          if (G.row === r && p === cur) { gPlay(); return; }
          G.row = r; G.cursor = Math.max(p.s, G.view) + 1; gRender();
        });
        line.appendChild(el);
      });
    }
    row.appendChild(c); row.appendChild(line);
    return row;
  }
  function gInfo(now) {
    var ch = G.list[G.row];
    if (!ch) return;
    var p = gSel(G.row);
    $('gd-ch').textContent = (ch.num ? ch.num + ' · ' : '') + ch.name;
    if (!p) {
      $('gd-title').textContent = ch.name;
      $('gd-time').textContent = G.data[ch.stream_id] === undefined ? 'Carregando guia...' : 'Sem programação para este canal';
      $('gd-desc').textContent = 'OK para assistir.';
      return;
    }
    $('gd-title').textContent = p.t;
    var when = dayLabel(p.s) + ', ' + hm(p.s) + ' – ' + hm(p.e);
    var extra = p.s <= now && p.e > now ? ' · <b>AGORA</b> · faltam ' + Math.ceil((p.e - now) / G_MIN) + ' min'
      : p.s > now ? ' · começa em ' + gIn(p.s - now) : ' · já passou';
    $('gd-time').innerHTML = esc(when) + extra;
    $('gd-desc').textContent = p.d || '';
  }
  function gIn(ms) { var m = Math.round(ms / G_MIN); return m < 60 ? m + ' min' : Math.floor(m / 60) + 'h' + (m % 60 ? pad(m % 60) : ''); }

  function gMoveRow(d) {
    var n = Math.max(0, Math.min(G.list.length - 1, G.row + d));
    if (n === G.row) return;
    G.row = n;
    if (G.row < G.top) G.top = G.row;
    if (G.row >= G.top + G_ROWS) G.top = G.row - G_ROWS + 1;
    gRender();
  }
  function gMoveTime(d) {
    var ch = G.list[G.row], l = ch && G.data[ch.stream_id], p = gSel(G.row);
    if (l && l.length && p) {
      var i = l.indexOf(p) + d;
      if (i < 0 || i >= l.length) return;
      var q = l[i];
      if (d < 0 && q.e < Date.now() - 3 * 3600000) return;   // não volta mais que 3h
      G.cursor = Math.max(q.s, d < 0 ? G.view - G_SPAN : q.s) + 1;
    } else {
      G.cursor += d * G_STEP;
    }
    // mantém o programa visível na janela de horários
    while (G.cursor >= G.view + G_SPAN - G_STEP) G.view += G_STEP;
    while (G.cursor < G.view) G.view -= G_STEP;
    gRender();
  }
  function gPlay() {
    if (!G.list[G.row]) return;
    playLive(G.list, G.row, G.catName, G.catId);
  }
  function guideKey(e) {
    var k = e.keyCode;
    switch (k) {
      case K.UP: gMoveRow(-1); return true;
      case K.DOWN: gMoveRow(1); return true;
      case K.LEFT: gMoveTime(-1); return true;
      case K.RIGHT: gMoveTime(1); return true;
      case K.CH_UP: case K.PAGE_UP: gMoveRow(-G_ROWS); return true;
      case K.CH_DOWN: case K.PAGE_DOWN: gMoveRow(G_ROWS); return true;
      case K.ENTER: gPlay(); return true;
    }
    return false;
  }
  $('gd-rows').addEventListener('wheel', function (e) { gMoveRow(e.deltaY > 0 ? 1 : -1); e.preventDefault(); });
