  /* ---- teste de conexão: baixa um trecho do último filme e mede a velocidade real até o servidor ---- */
  function connType() {
    if (!Platform.isTizen) return '';
    try {
      var t = webapis.network.getActiveConnectionType();
      return t === 1 ? 'wifi' : t === 3 ? 'cabo' : '';
    } catch (e) { return ''; }
  }
  function netTest() {
    var last = null;
    try { last = JSON.parse(localStorage.getItem('iptvs.lastVod') || 'null'); } catch (e) {}
    if (!last || !last.url) { toast('Abra um filme ou episódio uma vez e depois faça o teste.', 5000); return; }
    if (!Platform.isOnline()) { toast('Sem internet: verifique o Wi-Fi ou o cabo', 5000); return; }
    if (Player.isOpen()) return;
    var SECS = 10, MAX = 60 * 1024 * 1024;
    openDialog(function (box, d) {
      box.appendChild(h('h2', null, 'Teste de conexão'));
      var msg = h('p', null, 'Medindo a velocidade até o servidor da lista com "' + esc(last.title || 'último vídeo') + '"...');
      var bar = h('div', 'hero-prog', '<i style="width:0%"></i>');
      box.appendChild(msg); box.appendChild(bar);
      var btns = h('div', 'dlg-btns');
      btns.appendChild(dlgBtn('Fechar', function () { d.close(); }, true));
      box.appendChild(btns);

      var xhr = new XMLHttpRequest(), t0 = Date.now(), tFirst = 0, bytes = 0, total = 0, finished = false;
      var timer = setInterval(function () {
        if (d.closed) { stop(); return; }
        var el = tFirst ? (Date.now() - tFirst) / 1000 : 0;
        bar.firstChild.style.width = Math.min(100, (Date.now() - t0) / 10 / SECS) + '%';
        if (el > 0.5) msg.textContent = 'Medindo... ' + (bytes * 8 / el / 1e6).toFixed(1) + ' Mbps';
        if (Date.now() - t0 > SECS * 1000 + 4000) stop();
      }, 400);
      function stop() {
        if (finished) return;
        finished = true; clearInterval(timer);
        try { xhr.abort(); } catch (e) {}   // libera a conexão do plano
        if (!d.closed) result();
      }
      function result() {
        var el = tFirst ? Math.max(0.05, (Date.now() - tFirst) / 1000) : 0;
        var lat = tFirst ? tFirst - t0 : 0;
        bar.firstChild.style.width = '100%';
        if (!bytes) {
          msg.innerHTML = 'Não foi possível medir: o servidor da lista não respondeu.' +
            (lat > 8000 || !tFirst ? ' Ele pode estar fora do ar ou lento agora. Tente de novo em alguns minutos.' : '');
          return;
        }
        var mbps = bytes * 8 / el / 1e6;
        var need = total && last.dur ? total * 8 / last.dur / 1e6 : 0;
        var ct = connType();
        var lines = ['<b>Velocidade até o servidor: ' + mbps.toFixed(1) + ' Mbps</b>'];
        if (need) lines.push('Este vídeo usa cerca de ' + need.toFixed(1) + ' Mbps.');
        lines.push('Resposta do servidor: ' + (lat / 1000).toFixed(1) + ' s' + (ct ? ' · TV no ' + (ct === 'wifi' ? 'Wi-Fi' : 'cabo') : ''));
        var ref = need || 8, verdict;
        if (mbps >= ref * 1.8) verdict = 'Conexão boa para este conteúdo. Se ainda travar, a lentidão é momentânea no servidor da lista.';
        else if (mbps >= ref * 1.1) verdict = 'Conexão no limite: pode travar quando a rede oscilar.';
        else verdict = 'Conexão insuficiente para este conteúdo: vai travar.';
        lines.push(verdict);
        var tips = [];
        if (mbps < ref * 1.8) {
          if (ct === 'wifi') tips.push('Use cabo de rede na TV ou o Wi-Fi 5 GHz do roteador, e aproxime o roteador da TV.');
          tips.push('Se o YouTube/Netflix na mesma TV funciona bem, o limite está no servidor da lista (fale com quem fornece a lista).');
          if (lat > 3000) tips.push('O servidor está demorando para responder; costuma piorar à noite.');
        }
        msg.innerHTML = lines.join('<br>') + (tips.length ? '<br><br><small>' + tips.map(esc).join('<br>') + '</small>' : '');
      }
      xhr.open('GET', Platform.wrap(last.url));
      xhr.responseType = 'arraybuffer';
      try { xhr.setRequestHeader('Range', 'bytes=0-' + (MAX - 1)); } catch (e) {}
      xhr.onprogress = function (e) {
        if (!tFirst) { tFirst = Date.now(); bytes = 0; }
        bytes = e.loaded;
        if (!total) {
          var cr = xhr.getResponseHeader('Content-Range');
          var m = cr && cr.match(/\/(\d+)/);
          total = m ? +m[1] : (xhr.status === 200 ? +(xhr.getResponseHeader('Content-Length') || 0) : 0);
        }
        if ((tFirst && Date.now() - tFirst > SECS * 1000) || bytes >= MAX) stop();
      };
      xhr.onload = xhr.onerror = xhr.ontimeout = function () { stop(); };
      xhr.send();
    });
  }
